mapper.sql:
FROM ph_warehouse w
WHERE w.tenant_id = #{scope.tenantId} AND w.store_id = #{scope.storeId} AND w.deleted = 0
AND w.id = #{q.warehouseId}
AND LOCATE(#{q.code}, w.wh_code) > 0
AND LOCATE(#{q.name}, w.wh_name) > 0
AND w.status = #{q.status}

mapper.select:
SELECT id, store_id, wh_code, wh_name, temp_zone, is_default, status
FROM ph_warehouse
WHERE tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId} AND deleted = 0 AND id = #{id}

mapper.sql:
FROM ph_location l
JOIN ph_warehouse w ON w.id = l.warehouse_id AND w.tenant_id = l.tenant_id
WHERE l.tenant_id = #{scope.tenantId} AND w.tenant_id = #{scope.tenantId}
  AND w.store_id = #{scope.storeId} AND l.deleted = 0 AND w.deleted = 0
AND w.id = #{q.warehouseId}
AND l.id = #{q.locationId}
AND LOCATE(#{q.code}, l.location_code) > 0
AND l.status = #{q.status}

mapper.select:
SELECT l.id, l.warehouse_id, w.wh_name AS warehouse_name, l.location_code,
       l.location_type, l.max_capacity, l.status

ORDER BY l.id LIMIT #{q.pageSize} OFFSET #{q.offset}

mapper.sql:
FROM ph_inv_batch b
JOIN ph_warehouse w ON w.id = b.warehouse_id AND w.tenant_id = b.tenant_id AND w.store_id = b.store_id
WHERE b.tenant_id = #{scope.tenantId} AND w.tenant_id = #{scope.tenantId}
  AND b.store_id = #{scope.storeId} AND w.store_id = #{scope.storeId}
  AND b.deleted = 0 AND w.deleted = 0
AND b.warehouse_id = #{q.warehouseId}
AND b.drug_id = #{q.drugId}
AND b.id = #{q.batchId}
AND b.batch_no = #{q.batchNo}


    AND EXISTS (SELECT 1 FROM ph_inv_location_stock sx
        JOIN ph_location lx ON lx.id = sx.location_id AND lx.tenant_id = sx.tenant_id
        WHERE sx.batch_id = b.id AND sx.tenant_id = b.tenant_id AND sx.drug_id = b.drug_id
          AND sx.location_id = #{q.locationId} AND lx.warehouse_id = b.warehouse_id
          AND sx.deleted = 0 AND lx.deleted = 0)

mapper.select:
SELECT b.id, b.warehouse_id, w.wh_name AS warehouse_name, b.drug_id, b.batch_no,
       b.manufacture_date, b.expiry_date, b.qty_total, b.qty_avail, b.qty_frozen, b.qty_sold, b.quality_status

ORDER BY b.expiry_date, b.id LIMIT #{q.pageSize} OFFSET #{q.offset}

mapper.sql:
FROM ph_inv_location_stock s
JOIN ph_inv_batch b ON b.id = s.batch_id AND b.tenant_id = s.tenant_id AND b.drug_id = s.drug_id
JOIN ph_location l ON l.id = s.location_id AND l.tenant_id = s.tenant_id AND l.warehouse_id = b.warehouse_id
JOIN ph_warehouse w ON w.id = b.warehouse_id AND w.tenant_id = b.tenant_id AND w.store_id = b.store_id
WHERE s.tenant_id = #{scope.tenantId} AND b.tenant_id = #{scope.tenantId}
  AND l.tenant_id = #{scope.tenantId} AND w.tenant_id = #{scope.tenantId}
  AND b.store_id = #{scope.storeId} AND w.store_id = #{scope.storeId}
  AND s.deleted = 0 AND b.deleted = 0 AND l.deleted = 0 AND w.deleted = 0
AND b.warehouse_id = #{q.warehouseId}
AND s.drug_id = #{q.drugId}
AND s.batch_id = #{q.batchId}
AND s.location_id = #{q.locationId}
AND b.batch_no = #{q.batchNo}

mapper.select:
SELECT s.id, s.batch_id, b.batch_no, b.warehouse_id, s.location_id, l.location_code,
       s.drug_id, s.qty, s.qty_frozen, s.qty - s.qty_frozen AS qty_avail

ORDER BY s.batch_id, s.location_id LIMIT #{q.pageSize} OFFSET #{q.offset}

mapper.sql:
FROM ph_inv_flow f
WHERE f.tenant_id = #{scope.tenantId} AND f.store_id = #{scope.storeId} AND f.deleted = 0
AND f.id = #{q.flowId}
AND f.flow_type = #{q.flowType}
AND f.biz_type = #{q.bizType}
AND f.flow_time >= #{q.flowFrom}
AND f.flow_time < #{q.flowBefore}

    AND EXISTS (SELECT 1 FROM ph_inv_batch fb
        JOIN ph_warehouse fw ON fw.id = fb.warehouse_id AND fw.tenant_id = fb.tenant_id
                             AND fw.store_id = fb.store_id
        WHERE fb.id = f.batch_id AND fb.tenant_id = f.tenant_id AND fb.store_id = f.store_id
          AND fb.warehouse_id = #{q.warehouseId})

AND f.drug_id = #{q.drugId}
AND f.batch_id = #{q.batchId}
AND f.location_id = #{q.locationId}
AND f.batch_no = #{q.batchNo}
AND f.biz_no = #{q.bizNo}

mapper.select:
SELECT f.id, f.batch_id, f.batch_no, f.drug_id, f.location_id, f.flow_type,
       f.in_qty, f.out_qty, f.frozen_delta, f.balance_qty, f.biz_type, f.biz_no, f.biz_line_id, f.flow_time

ORDER BY f.id DESC LIMIT #{q.pageSize} OFFSET #{q.offset}
